// Collect results from all three GitHub API calls
const commits = $('Get Commits (7d)').all().map(item => item.json);
const closedIssues = $('Get Closed Issues (7d)').all().map(item => item.json);
const mergedPRs = $('Get Merged PRs (7d)').all().map(item => item.json);

// Extract commit summaries
const commitList = Array.isArray(commits[0]) ? commits[0] : commits;
const commitSummaries = commitList.slice(0, 50).map(c => ({
  sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
  message: c.commit ? c.commit.message.split('\n')[0] : (c.message || 'No message'),
  author: c.commit ? (c.commit.author ? c.commit.author.name : 'unknown') : (c.author || 'unknown'),
  date: c.commit ? (c.commit.author ? c.commit.author.date : '') : ''
}));

// Extract closed issues (filter out PRs — GitHub includes PRs in issues endpoint)
const issueList = Array.isArray(closedIssues[0]) ? closedIssues[0] : closedIssues;
const issueSummaries = issueList
  .filter(i => !i.pull_request)
  .slice(0, 50)
  .map(i => ({
    number: i.number,
    title: i.title,
    closed_at: i.closed_at,
    labels: i.labels ? i.labels.map(l => l.name).join(', ') : ''
  }));

// Extract merged PRs from search results
const prData = mergedPRs[0] && mergedPRs[0].items ? mergedPRs[0].items : (Array.isArray(mergedPRs[0]) ? mergedPRs[0] : mergedPRs);
const prSummaries = prData.slice(0, 50).map(pr => ({
  number: pr.number,
  title: pr.title,
  merged_at: pr.pull_request ? pr.pull_request.merged_at : pr.closed_at,
  user: pr.user ? pr.user.login : 'unknown'
}));

const config = $('Config Variables').first().json;

return [{
  json: {
    owner: config.GITHUB_OWNER,
    repo: config.GITHUB_REPO,
    language: config.LANGUAGE,
    discord_webhook: config.DISCORD_WEBHOOK_URL,
    anthropic_key: config.ANTHROPIC_API_KEY,
    period_start: $now.minus(7, 'days').format('yyyy-MM-dd'),
    period_end: $now.format('yyyy-MM-dd'),
    stats: {
      total_commits: commitSummaries.length,
      total_issues_closed: issueSummaries.length,
      total_prs_merged: prSummaries.length
    },
    commits: commitSummaries,
    issues_closed: issueSummaries,
    prs_merged: prSummaries
  }
}];

