// Extract Claude's response and format for Discord
const claudeResponse = $input.first().json;
const prevData = $('Merge & Format Data').first().json;

// Extract text from Claude API response
let summary = '';
if (claudeResponse.content && claudeResponse.content.length > 0) {
  summary = claudeResponse.content[0].text;
} else {
  summary = 'Summary generation failed. Raw response: ' + JSON.stringify(claudeResponse).substring(0, 500);
}

// Build Discord message with header
const repoName = `${prevData.owner}/${prevData.repo}`;
const header = `**Weekly Dev Summary** | ${repoName} | ${prevData.period_start} to ${prevData.period_end}`;
const stats = `Commits: ${prevData.stats.total_commits} | Issues Closed: ${prevData.stats.total_issues_closed} | PRs Merged: ${prevData.stats.total_prs_merged}`;

// Discord message limit is 2000 chars
let fullMessage = `${header}\n${stats}\n\n${summary}`;
if (fullMessage.length > 1990) {
  fullMessage = fullMessage.substring(0, 1987) + '...';
}

return [{
  json: {
    discord_webhook: prevData.discord_webhook,
    message: fullMessage
  }
}];
